# Create grid and find connected components (including diagonal adjacency)
grid = np.zeros((17, 23), dtype=bool)
for r, c in preserved:
    grid[r, c] = True

visited = set()
components = []

def dfs(r, c):
    stack = [(r, c)]
    comp = []
    while stack:
        cur_r, cur_c = stack.pop()
        if (cur_r, cur_c) in visited:
            continue
        visited.add((cur_r, cur_c))
        comp.append((cur_r, cur_c))

        # Check all 8 neighbors
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = cur_r + dr, cur_c + dc
                if 0 <= nr < 17 and 0 <= nc < 23:
                    if grid[nr, nc] and (nr, nc) not in visited:
                        stack.append((nr, nc))
    return comp

for r in range(17):
    for c in range(23):
        if grid[r, c] and (r, c) not in visited:
            comp = dfs(r, c)
            if comp:
                components.append(comp)

print(f"Number of connected components: {len(components)}")
for i, comp in enumerate(components):
